"""Shared branding constants for the pages ster generates.

A single inline (data URI) favicon, so every page — the taxonomy/graph app
shell, the query map — carries the same tab icon without depending on a
static-file route: ``ster show``'s standalone HTML export serves only the
cache directory it writes to, not :mod:`ster.assets`, so a file-based icon
would 404 there. The SVG is the ``ster`` wordmark's own "S" glyph (traced
outline, supplied as the source of truth), scaled and centered on the app's
own slate-100 background (``#f1f5f9``).
"""

from __future__ import annotations

FAVICON_LINK_TAG = (
    '<link rel="icon" type="image/svg+xml" href="data:image/svg+xml;base64,'
    ""
    '">'
)
